162	// expandProseResolution spends the result slots the distinct-file ranking left empty on the finer
163	// regions it already computed, without breaching the caller's byte ceiling.
164	func expandProseResolution(results []SearchResult, topK, budget int) []SearchResult {
165		if topK <= 0 || len(results) >= topK {
166			return results
167		}
168		order := planProseResolutionPromotions(results, topK-len(results))
169		if len(order) == 0 {
170			return results
171		}
172		if budget <= 0 {
173			return applyProseResolutionPromotions(results, order, len(order))
174		}
175		// Serialized size is strictly increasing in count: a promotion always moves a passage out of a
176		// `passages` entry and into a full result record, which is strictly larger. The largest fitting
177		// count is therefore found by bisection in ~log2(n) serializations rather than by materializing
178		// and marshalling the whole result set once per candidate count.
179		low, high := 0, len(order)
180		for low < high {
181			mid := (low + high + 1) / 2
182			if serializedSearchResultBytes(applyProseResolutionPromotions(results, order, mid)) <= budget {
183				low = mid
184			} else {
185				high = mid - 1
186			}
187		}
188		if low == 0 {
189			return results
190		}
191		return applyProseResolutionPromotions(results, order, low)
192	}
