93	// applyProseResolutionPromotions materializes the first `count` planned promotions. The promoted
94	// passages leave their parent, so no region is returned twice, and the parents keep the passages
95	// that were not promoted (a suffix of a source-ordered, non-overlapping list stays source-ordered
96	// and non-overlapping, which is what SearchResponse.Validate requires).
97	func applyProseResolutionPromotions(results []SearchResult, order []prosePromotion, count int) []SearchResult {
98		promotedFrom := make([]map[int]bool, len(results))
99		for _, promotion := range order[:count] {
100			if promotedFrom[promotion.parent] == nil {
101				promotedFrom[promotion.parent] = map[int]bool{}
102			}
103			promotedFrom[promotion.parent][promotion.passage] = true
104		}
105		expanded := make([]SearchResult, 0, len(results)+count)
106		for index := range results {
107			parent := results[index]
108			if promotedFrom[index] != nil {
109				kept := make([]SearchPassage, 0, len(parent.Passages))
110				for passageIndex, passage := range parent.Passages {
111					if !promotedFrom[index][passageIndex] {
112						kept = append(kept, passage)
113					}
114				}
115				if len(kept) == 0 {
116					kept = nil
117				}
118				parent.Passages = kept
119			}
120			expanded = append(expanded, parent)
121		}
122		for _, promotion := range order[:count] {
123			expanded = append(expanded, proseResolutionResult(results[promotion.parent], results[promotion.parent].Passages[promotion.passage]))
124		}
125		// results[] is documented as descending by score, and consumers truncate on it. Appending
126		// promotions would break that: a promotion carries its parent's score, so a passage of a
127		// high-scoring document landed after every low-scoring parent and the array stopped being
128		// monotone. Re-sorting restores the invariant, and a STABLE sort is what makes it safe --
129		// a promotion ties with its parent exactly, so it settles immediately after that parent
130		// instead of anywhere else in the tie. Set membership is untouched, so promotion stays
131		// strictly additive; only the order it is reported in changes.
132		sort.SliceStable(expanded, func(i, j int) bool { return expanded[i].Score > expanded[j].Score })
133		for index := range expanded {
134			expanded[index].Rank = index + 1
135		}
136		return expanded
137	}
